import { JsonSchema } from "../json-schema.js";
import { StringEnum as localStringEnum } from "../string-enum-schema.js";
import { AGENT_BROWSER_SCRIPT_CODE_MAX_BYTES } from "./script.js";
import { ELECTRON_DISCOVERY_DEFAULT_MAX_RESULTS, ELECTRON_DISCOVERY_MAX_RESULTS, } from "../electron/discovery.js";
import { AGENT_BROWSER_ELECTRON_HANDOFFS, AGENT_BROWSER_ELECTRON_TARGET_TYPES, AGENT_BROWSER_JOB_STEP_ACTIONS, AGENT_BROWSER_JOB_TYPE_DELAYED_TEXT_MAX_CHARACTERS, AGENT_BROWSER_QA_LOAD_STATES, AGENT_BROWSER_SEMANTIC_ACTIONS, AGENT_BROWSER_SEMANTIC_LOCATORS, DEFAULT_SESSION_MODE, SOURCE_LOOKUP_MAX_WORKSPACE_FILES, } from "./types.js";
// Keep descriptions terse: Pi sends this schema every turn; workflows belong in prompt guidance and docs.
export function createAgentBrowserParamsSchema(Type = JsonSchema, StringEnum = localStringEnum) {
    return Type.Object({
        script: Type.Optional(Type.String({
            description: "One-shot JavaScript orchestration with async browser({ args, stdin?, timeoutMs? }) and emit(value); isolated session and no host access.",
            maxLength: AGENT_BROWSER_SCRIPT_CODE_MAX_BYTES,
        })),
        args: Type.Optional(Type.Array(Type.String(), {
            description: "Raw agent-browser argv only: no binary, shell operators, or --json. Start with open → snapshot -i → act on current @refs; re-snapshot after page changes. Input: type <selector> <text>, or keyboard type <text> at current focus. Wait duration: wait <ms> (no --time). Artifacts: screenshot [selector] [path] [--full/-f]; record start <path> [url]; record restart <path> [url]; record stop. Paths are positional (no --path); use --full, not --full-page.",
            minItems: 1,
        })),
        semanticAction: Type.Optional(Type.Object({
            action: StringEnum(AGENT_BROWSER_SEMANTIC_ACTIONS),
            locator: Type.Optional(StringEnum(AGENT_BROWSER_SEMANTIC_LOCATORS, { description: "Locator for check/click/fill; select supports role or label." })),
            value: Type.Optional(Type.String({ description: "Locator value or one select option; for select by label, this is the label text." })),
            values: Type.Optional(Type.Array(Type.String(), { description: "Select options; required for select by label.", minItems: 1 })),
            selector: Type.Optional(Type.String({ description: "Direct selector or @ref." })),
            text: Type.Optional(Type.String({ description: "Fill text." })),
            role: Type.Optional(Type.String({ description: "Role for locator=role; select needs combobox or listbox." })),
            name: Type.Optional(Type.String({ description: "Accessible name." })),
            session: Type.Optional(Type.String({ description: "Upstream session name." })),
        }, {
            additionalProperties: false,
            // Pi normalizes optional nulls through properties, not union branches.
            anyOf: [
                Type.Object({
                    action: StringEnum(["select"]),
                    locator: Type.Optional(StringEnum(["role", "label"])),
                }, { not: { required: ["text"] } }),
                Type.Object({
                    action: StringEnum(["check", "click", "fill"]),
                }, { not: { required: ["values"] } }),
            ],
            description: "Stable locator or direct-selector action. values only with action=select.",
        })),
        qa: Type.Optional(Type.Union([
            Type.Object({
                attached: Type.Literal(true),
                expectedText: Type.Optional(Type.Union([Type.String(), Type.Array(Type.String())])),
                expectedSelector: Type.Optional(Type.String()),
                screenshotPath: Type.Optional(Type.String()),
                checkConsole: Type.Optional(Type.Boolean()),
                checkErrors: Type.Optional(Type.Boolean()),
                checkNetwork: Type.Optional(Type.Boolean()),
                loadState: Type.Optional(StringEnum(AGENT_BROWSER_QA_LOAD_STATES)),
            }, { additionalProperties: false }),
            Type.Object({
                url: Type.String(),
                attached: Type.Optional(Type.Literal(false)),
                expectedText: Type.Optional(Type.Union([Type.String(), Type.Array(Type.String())])),
                expectedSelector: Type.Optional(Type.String()),
                screenshotPath: Type.Optional(Type.String()),
                checkConsole: Type.Optional(Type.Boolean()),
                checkErrors: Type.Optional(Type.Boolean()),
                checkNetwork: Type.Optional(Type.Boolean()),
                loadState: Type.Optional(StringEnum(AGENT_BROWSER_QA_LOAD_STATES)),
            }, { additionalProperties: false }),
        ], { description: "QA a URL or current session (attached=true). Default readiness: domcontentloaded; use networkidle only without long-lived requests. URL diagnostics default on, attached diagnostics off." })),
        sourceLookup: Type.Optional(Type.Object({
            selector: Type.Optional(Type.String({ description: "Visible selector or @ref." })),
            reactFiberId: Type.Optional(Type.String({ description: "React fiber id; requires --enable react-devtools." })),
            componentName: Type.Optional(Type.String({ description: "Component for local source search." })),
            includeDomHints: Type.Optional(Type.Boolean({ description: "Inspect DOM source hints; default true." })),
            maxWorkspaceFiles: Type.Optional(Type.Number({ description: "Source scan cap; default 2000.", minimum: 1, maximum: SOURCE_LOOKUP_MAX_WORKSPACE_FILES })),
        }, { additionalProperties: false, description: "EXPERIMENTAL UI-to-source candidates; not guaranteed mappings." })),
        networkSourceLookup: Type.Optional(Type.Object({
            filter: Type.Optional(Type.String({ description: "Network request filter." })),
            namespace: Type.Optional(Type.String()),
            requestId: Type.Optional(Type.String({ description: "Request id to inspect." })),
            session: Type.Optional(Type.String()),
            url: Type.Optional(Type.String({ description: "Failed URL or fragment." })),
            maxWorkspaceFiles: Type.Optional(Type.Number({ description: "Source scan cap; default 2000.", minimum: 1, maximum: SOURCE_LOOKUP_MAX_WORKSPACE_FILES })),
        }, { additionalProperties: false, description: "EXPERIMENTAL failed-request-to-source candidates; not proof." })),
        electron: Type.Optional(Type.Union([
            Type.Object({
                action: StringEnum(["list"]),
                query: Type.Optional(Type.String({ description: "Case-insensitive app filter.", minLength: 1 })),
                maxResults: Type.Optional(Type.Integer({ description: `Result cap; default ${ELECTRON_DISCOVERY_DEFAULT_MAX_RESULTS}, values over ${ELECTRON_DISCOVERY_MAX_RESULTS} are clamped.`, minimum: 1 })),
            }, { additionalProperties: false }),
            Type.Object({
                action: StringEnum(["launch"]),
                appPath: Type.Optional(Type.String({ description: "macOS .app path.", minLength: 1 })),
                appName: Type.Optional(Type.String({ description: "Name from electron.list.", minLength: 1 })),
                bundleId: Type.Optional(Type.String({ description: "Bundle id from electron.list.", minLength: 1 })),
                executablePath: Type.Optional(Type.String({ description: "Executable path.", minLength: 1 })),
                appArgs: Type.Optional(Type.Array(Type.String({ minLength: 1 }))),
                handoff: Type.Optional(StringEnum(AGENT_BROWSER_ELECTRON_HANDOFFS)),
                targetType: Type.Optional(StringEnum(AGENT_BROWSER_ELECTRON_TARGET_TYPES)),
                timeoutMs: Type.Optional(Type.Integer({ minimum: 1 })),
                allow: Type.Optional(Type.Array(Type.String({ minLength: 1 }))),
                deny: Type.Optional(Type.Array(Type.String({ minLength: 1 }))),
            }, { additionalProperties: false }),
            Type.Object({
                action: StringEnum(["status", "cleanup"]),
                launchId: Type.String({ description: "Tracked launch id.", minLength: 1 }),
                timeoutMs: Type.Optional(Type.Integer({ minimum: 1 })),
            }, { additionalProperties: false }),
            Type.Object({
                action: StringEnum(["status", "cleanup"]),
                all: Type.Literal(true),
                timeoutMs: Type.Optional(Type.Integer({ minimum: 1 })),
            }, { additionalProperties: false }),
            Type.Object({
                action: StringEnum(["status", "cleanup"]),
                timeoutMs: Type.Optional(Type.Integer({ minimum: 1 })),
            }, { additionalProperties: false }),
            Type.Object({
                action: StringEnum(["probe"]),
                launchId: Type.Optional(Type.String({ description: "Tracked launch id.", minLength: 1 })),
                timeoutMs: Type.Optional(Type.Integer({ minimum: 1 })),
            }, { additionalProperties: false }),
        ], { description: "Electron discovery, isolated-profile launch, status, probe, or cleanup. Launch defaults: handoff=snapshot, targetType=page; deny wins over allow; lifecycle/debug appArgs rejected." })),
        job: Type.Optional(Type.Object({
            failFast: Type.Optional(Type.Boolean({ description: "Stop on first failure; default true." })),
            steps: Type.Array(Type.Object({
                action: StringEnum(AGENT_BROWSER_JOB_STEP_ACTIONS),
                url: Type.Optional(Type.String({ description: "Open URL, or assertUrl exact URL/glob that distinguishes the expected state from the starting page." })),
                loadState: Type.Optional(StringEnum(AGENT_BROWSER_QA_LOAD_STATES, { description: "Readiness wait after open." })),
                selector: Type.Optional(Type.String({ description: "Selector or @ref." })),
                locator: Type.Optional(StringEnum(AGENT_BROWSER_SEMANTIC_LOCATORS, { description: "Locator when selector is omitted." })),
                role: Type.Optional(Type.String({ description: "Role locator." })),
                name: Type.Optional(Type.String({ description: "Accessible name." })),
                text: Type.Optional(Type.String({ description: "Fill/type text; assertText uses only text, not selector/locator fields." })),
                value: Type.Optional(Type.String({ description: "Select option or locator value." })),
                values: Type.Optional(Type.Array(Type.String(), { description: "Select options.", minItems: 1 })),
                path: Type.Optional(Type.String({ description: "Download or screenshot path." })),
                delayMs: Type.Optional(Type.Integer({ description: `Per-character type delay; text is capped at ${AGENT_BROWSER_JOB_TYPE_DELAYED_TEXT_MAX_CHARACTERS} characters.`, minimum: 1 })),
                press: Type.Optional(Type.String({ description: "Key to press after typing." })),
                milliseconds: Type.Optional(Type.Number({ description: "Wait duration in milliseconds." })),
            }, { additionalProperties: false }), { minItems: 1 }),
        }, { additionalProperties: false, description: "Constrained multi-step batch. Clicks can stale later refs; split and re-snapshot before using them." })),
        stdin: Type.Optional(Type.String({ description: "For batch, a JSON array of token arrays, e.g. [[\"get\",\"title\"]]. Raw text only for eval --stdin or auth save --password-stdin; unavailable with structured modes and electron." })),
        outputPath: Type.Optional(Type.String({ description: "Workspace-relative or absolute result-data path; keep it distinct from screenshot, download, recording, and other browser artifact destinations.", minLength: 1 })),
        timeoutMs: Type.Optional(Type.Integer({ description: "Wrapper timeout in ms; exceed explicit waits. electron.list has no configurable timeout; other Electron actions use electron.timeoutMs.", minimum: 1 })),
        sessionMode: Type.Optional(StringEnum(["auto", "fresh"], {
            description: "Native configured sessions win; otherwise auto reuses the managed session and fresh starts a new managed browser for launch-only flags.",
            default: DEFAULT_SESSION_MODE,
        })),
        debug: Type.Optional(Type.Object({
            url: Type.Optional(Type.String({ description: "Open this URL first (adds a readiness wait)." })),
            expectedText: Type.Optional(Type.Union([Type.String(), Type.Array(Type.String())])),
            expectedSelector: Type.Optional(Type.String()),
            evalExpression: Type.Optional(Type.String({ description: "One bounded page expression; its result is included in the report." })),
            screenshotPath: Type.Optional(Type.String()),
            checkConsole: Type.Optional(Type.Boolean({ description: "Include console errors; default true." })),
            checkErrors: Type.Optional(Type.Boolean({ description: "Include page errors; default true." })),
            checkNetwork: Type.Optional(Type.Boolean({ description: "Include failed requests; default true." })),
            networkFilter: Type.Optional(Type.String()),
            loadState: Type.Optional(StringEnum(AGENT_BROWSER_QA_LOAD_STATES)),
            maxFailures: Type.Optional(Type.Integer({ description: "Cap on listed failed requests; default 10.", minimum: 1 })),
        }, { additionalProperties: false, description: "One-shot devtools report: url/title, console, page errors, failed requests, bounded snapshot, optional eval result. Replaces four separate diagnostic calls." })),
        settle: Type.Optional(Type.Object({
            quietMs: Type.Optional(Type.Integer({ description: "Required quiet window; default 500.", minimum: 1 })),
            timeoutMs: Type.Optional(Type.Integer({ description: "Give up after this long; default 10000.", minimum: 1 })),
            requireNetworkIdle: Type.Optional(Type.Boolean({ description: "Wait for no new resource entries; default true." })),
            requireDomStable: Type.Optional(Type.Boolean({ description: "Wait for no DOM mutations; default true." })),
        }, { additionalProperties: false, description: "Wait until the page is actually quiet (no new resources and no DOM mutations for quietMs), then report what it observed." })),
        networkBody: Type.Optional(Type.Object({
            requestId: Type.Optional(Type.String({ description: "Request id from a `network requests` row." })),
            urlFilter: Type.Optional(Type.String({ description: "Substring filter when the id is not known yet." })),
            direction: Type.Optional(StringEnum(["response", "request", "both"])),
            maxChars: Type.Optional(Type.Integer({ description: "Body preview cap; default 4000.", minimum: 1 })),
        }, { additionalProperties: false, description: "Bounded body preview for one request (needs requestId to actually fetch a body). Honest about bodies upstream does not expose." })),
        vault: Type.Optional(Type.Object({
            action: StringEnum(["status", "list", "save", "fill", "totp", "remove", "unlock"]),
            handle: Type.Optional(Type.String({ description: "Vault entry handle.", minLength: 1 })),
            origin: Type.Optional(Type.String({ description: "Exact origin, for example https://app.example.com. Required for fill/save; with a handle, fill also accepts a handle-only call and verifies against the entry." })),
            type: Type.Optional(StringEnum(["login", "totp", "card", "address"])),
            username: Type.Optional(Type.String({ description: "Login identifier; visible metadata, not a secret." })),
            label: Type.Optional(Type.String()),
            secret: Type.Optional(Type.String({ description: "Prefer letting the user type the secret in the masked prompt; only pass this from a trusted host source." })),
            otpSeed: Type.Optional(Type.String({ description: "Authenticator setup key or otpauth:// URI." })),
            card: Type.Optional(Type.Object({}, { additionalProperties: true })),
            address: Type.Optional(Type.Object({}, { additionalProperties: true })),
            fields: Type.Optional(Type.Array(Type.Object({}, { additionalProperties: true }), { description: "Roles to fill, for example [{ role: \"password\" }].", minItems: 1 })),
            visibleFields: Type.Optional(Type.Array(Type.String(), { description: "Non-secret roles you may type yourself (username, card_name, address_*)." })),
            submit: Type.Optional(Type.Boolean({ description: "Submit after filling; default false." })),
            overwrite: Type.Optional(Type.Boolean({ description: "Replace an existing entry with the same handle." })),
            promptIfMissing: Type.Optional(Type.Boolean({ description: "Report how to save a missing login; default true." })),
            session: Type.Optional(Type.String({ description: "Upstream session name to target for fill/totp, for example ultron1." })),
            minutes: Type.Optional(Type.Integer({ description: "Unlock cache minutes; default 30.", minimum: 1 })),
        }, { additionalProperties: false, description: "Credential vault: list saved metadata, save a new entry (masked prompt), fill a saved login/card/address into the current page, enter a 2FA code, remove an entry, or unlock. Secrets are never returned and fills require an exact origin match." })),
        devServer: Type.Optional(Type.Object({
            action: StringEnum(["detect", "wait", "start", "stop", "status"]),
            command: Type.Optional(Type.String({ description: "Command to run for action=start.", minLength: 1 })),
            port: Type.Optional(Type.Integer({ description: "Dev server port.", minimum: 1, maximum: 65535 })),
            url: Type.Optional(Type.String()),
            timeoutMs: Type.Optional(Type.Integer({ description: "Readiness budget; default 30000.", minimum: 1 })),
        }, { additionalProperties: false, description: "Local dev server: detect candidates from package.json, wait for readiness, start an owned process, stop it, or report status. Host-only; no browser session is used." })),
        login: Type.Optional(Type.Object({
            url: Type.Optional(Type.String()),
            origin: Type.Optional(Type.String({ description: "Required when a vault secret is filled." })),
            handle: Type.Optional(Type.String({ description: "Vault handle to fill from." })),
            username: Type.Optional(Type.String()),
            usernameSelector: Type.Optional(Type.String()),
            passwordSelector: Type.Optional(Type.String()),
            otpSelector: Type.Optional(Type.String()),
            submitSelector: Type.Optional(Type.String()),
            password: Type.Optional(Type.String({ description: "Prefer the vault handle; only pass this from a trusted host source." })),
            otp: Type.Optional(Type.String({ description: "One-time code entered into the page; never printed back." })),
            otpSeed: Type.Optional(Type.String({ description: "Authenticator setup key or otpauth:// URI for totp." })),
            totp: Type.Optional(Type.Boolean({ description: "Mint the code from the authenticator seed instead of prompting." })),
            submit: Type.Optional(Type.Boolean()),
            settleAfterEachStep: Type.Optional(Type.Boolean({ description: "Wait for page readiness after submit; default true." })),
            waitForUrl: Type.Optional(Type.String()),
            waitForText: Type.Optional(Type.String()),
            loadStatePath: Type.Optional(Type.String()),
            saveStatePath: Type.Optional(Type.String()),
            session: Type.Optional(Type.String({ description: "Upstream session name to target." })),
            timeoutMs: Type.Optional(Type.Integer({ minimum: 1 })),
        }, { additionalProperties: false, description: "Login preset: optionally load state, open the page, fill the vault credential (offset-checked origin), submit, wait for the destination, and optionally save state. The password only ever travels to the page." })),
        revealSecrets: Type.Optional(Type.Object({
            headers: Type.Array(Type.String({ minLength: 1 }), { description: "Header names to reveal, for example [\"authorization\"].", minItems: 1, maxItems: 8 }),
            urlFilter: Type.Optional(Type.String({ description: "Required for `network requests`; limits revealed rows to matching URLs." })),
        }, { additionalProperties: false, description: "Explicit, per-call opt-in that stops redacting the named headers on matching network rows. Prints a warning and suppresses the spill file. Use only for auth debugging." })),
        verbosity: Type.Optional(StringEnum(["quiet", "normal", "verbose"], {
            description: "Model-visible prose level. quiet drops the diagnostic blocks and the next-action list (details keep everything); verbose adds the long-form sections. Default normal.",
        })),
    }, {
        additionalProperties: false,
        description: "Choose one input mode: script, args, semanticAction, job, qa, sourceLookup, networkSourceLookup, electron, debug, settle, networkBody, vault, devServer, or login.",
    });
}
export const AGENT_BROWSER_PARAMS = createAgentBrowserParamsSchema();
